{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for u, v, d in dists:
        w = max(core[u], core[v], d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == len(nodes) - 1:
                break
    if len(mst) != len(nodes) - 1:
        raise ValueError('Disconnected graph')
    return {'mst_edges': mst, 'total_weight': total}"
}
